const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let state={user:null,token:localStorage.getItem('bj_token')||'',settings:{},dashboard:null};
const api=async(path,opts={})=>{const h={...(opts.body?{'Content-Type':'application/json'}:{}),...(state.token?{Authorization:'Bearer '+state.token}:{})};const r=await fetch(path,{...opts,headers:{...h,...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'REQUEST_ERROR');return d};
const esc=s=>String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
function toast(m){const t=document.createElement('div');t.className='toast-item';t.textContent=m;$('#toast').appendChild(t);setTimeout(()=>t.remove(),3800)}
function toggleNav(){$('#publicNav').classList.toggle('open')}
function closeModal(){$('#modal').classList.add('hidden')}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}
function openLogin(pre=''){modal(`<div class="section-head"><span class="eyebrow">AKSES RESMI</span><h2>Login</h2><p>Admin, Guru, dan Murid login menggunakan Email dan Password.</p></div><form onsubmit="login(event)" class="form-grid"><div class="full"><label>Peran</label><select id="loginRole" onchange="toggleLoginFields()" required><option value="">Pilih Peran</option><option value="ADMIN">Admin</option><option value="GURU">Guru</option><option value="MURID">Murid</option></select></div><div><label>Email</label><input id="loginEmail" type="email" required></div><div id="loginPasswordWrap" class="full"><label>Password</label><input id="loginPassword" type="password" required></div><div class="form-actions full"><button class="btn">LOGIN</button></div><div class="full" style="margin-top:8px"><button type="button" class="btn secondary" onclick="openInitialPassword()">BUAT PASSWORD PERTAMA KALI</button></div></form>`);toggleLoginFields();if(pre){$('#loginRole').value=pre;toggleLoginFields();$('#loginEmail').focus()}}
function openInitialPassword(){modal(`<div class="section-head"><span class="eyebrow">AKUN AKTIF</span><h2>Buat Password</h2><p>Password dibuat sendiri oleh Guru/Murid setelah akun diaktifkan Admin.</p></div><form onsubmit="setInitialPassword(event)" class="form-grid"><div class="full"><label>Peran</label><select id="setRole" required><option value="GURU">Guru</option><option value="MURID">Murid</option></select></div><div><label>Email</label><input id="setEmail" type="email" required></div><div><label>WhatsApp</label><input id="setWa" required></div><div><label>Password Baru</label><input id="setPassword" type="password" minlength="8" required></div><div><label>Konfirmasi Password</label><input id="setPassword2" type="password" minlength="8" required></div><div class="form-actions full"><button class="btn">SIMPAN PASSWORD</button></div></form>`)}
async function setInitialPassword(e){e.preventDefault();if($('#setPassword').value!==$('#setPassword2').value)return toast('Konfirmasi password tidak sama.');try{const d=await api('/api/auth/set-initial-password',{method:'POST',body:JSON.stringify({role:$('#setRole').value,email:$('#setEmail').value,whatsapp:$('#setWa').value,password:$('#setPassword').value})});toast(d.message);openLogin($('#setRole').value)}catch(x){toast(x.message==='ACCOUNT_NOT_ACTIVE'?'Akun belum aktif.':x.message==='IDENTITY_DATA_INVALID'?'Email atau WhatsApp tidak sesuai data pendaftaran.':x.message==='PASSWORD_ALREADY_SET'?'Password akun sudah pernah dibuat.':x.message)}}
function toggleLoginFields(){const role=$('#loginRole')?.value;const pw=$('#loginPassword');if(!pw)return;pw.required=!!role;}
async function login(e){e.preventDefault();try{const role=$('#loginRole').value;const body={role,email:$('#loginEmail').value,password:$('#loginPassword').value};const d=await api('/api/login',{method:'POST',body:JSON.stringify(body)});state.token=d.token;state.user=d.user;localStorage.setItem('bj_token',state.token);closeModal();showDashboard();toast('Login berhasil.')}catch(x){toast(x.message==='ACCOUNT_NOT_ACTIVE'?'Akun belum aktif atau masih menunggu verifikasi.':x.message==='EMAIL_OR_PASSWORD_INVALID'?'Email atau password salah.':x.message)}}
async function forgotPassword(){const email=prompt('Masukkan email akun:');if(!email)return;try{const d=await api('/api/auth/forgot',{method:'POST',body:JSON.stringify({email})});toast(d.message)}catch(x){toast(x.message)}}
function openRegister(){modal(`<div class="section-head"><span class="eyebrow">PENDAFTARAN</span><h2>Pilih Pendaftaran</h2><p>Pendaftaran masuk ke sistem terlebih dahulu. Akun Guru menunggu verifikasi Admin; akun Murid mengikuti proses persetujuan.</p></div><div class="cards three"><article><h3>Daftar Jadi Guru</h3><p>Isi data Guru, program yang diajarkan, foto, alamat, dan pengalaman.</p><button class="btn" onclick="openTeacherRegister()">DAFTAR GURU</button></article><article><h3>Daftar Jadi Murid</h3><p>Pilih program, paket, dan Guru yang tersedia.</p><button class="btn" onclick="openStudentRegister()">DAFTAR MURID</button></article></div>`)}

async function openPrivateFile(path){
  try{
    const r=await fetch('/api/private-file?path='+encodeURIComponent(path),{headers:state.token?{Authorization:'Bearer '+state.token}:{}});
    if(!r.ok) throw new Error('FILE_ACCESS_DENIED');
    const blob=await r.blob(); const url=URL.createObjectURL(blob); window.open(url,'_blank','noopener');
    setTimeout(()=>URL.revokeObjectURL(url),60000);
  }catch(e){toast('File tidak dapat dibuka. Silakan login kembali.')}
}
function privateFileButton(path,label='Buka'){return path?`<button class="btn small outline" onclick='openPrivateFile(${JSON.stringify(path)})'>${esc(label)}</button>`:'-'}

function fileToDataUrl(input){return new Promise((resolve,reject)=>{const f=input.files[0];if(!f)return resolve('');if(f.size>8*1024*1024)return reject(new Error('Ukuran file maksimal 8 MB.'));const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)})}
async function openTeacherRegister(){modal(`<div class="section-head"><span class="eyebrow">PENDAFTARAN GURU</span><h2>Daftar Jadi Guru</h2></div><form onsubmit="registerTeacher(event)" class="form-grid"><div><label>Nama Lengkap</label><input id="gName" required></div><div><label>Nomor WhatsApp</label><input id="gWa" required></div><div><label>Email</label><input id="gEmail" type="email" required></div><div><label>Password</label><input id="gPassword" type="password" minlength="8" required></div><div><label>Konfirmasi Password</label><input id="gPassword2" type="password" minlength="8" required></div><div><label>Foto Profil</label><input id="gPhoto" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="full"><label>Program yang Diajarkan</label><div class="chips"><label><input type="checkbox" name="gprog" value="TAHFIDZ"> Tahfidz</label><label><input type="checkbox" name="gprog" value="TAHSIN"> Tahsin</label><label><input type="checkbox" name="gprog" value="TAFSIR"> Tafsir</label></div></div><div class="full"><label>Alamat</label><textarea id="gAddress"></textarea></div><div class="full"><label>Keterangan/Pengalaman Mengajar</label><textarea id="gExp"></textarea></div><div class="form-actions full"><button class="btn">DAFTAR</button></div><p class="hint full">Password digunakan untuk login setelah akun disetujui Admin.</p></form>`)}
async function registerTeacher(e){e.preventDefault();if($('#gPassword').value!==$('#gPassword2').value)return toast('Konfirmasi password tidak sama.');try{const photo=await fileToDataUrl($('#gPhoto'));const programs=$$('input[name="gprog"]:checked').map(x=>x.value);const d=await api('/api/register/guru',{method:'POST',body:JSON.stringify({name:$('#gName').value,whatsapp:$('#gWa').value,email:$('#gEmail').value,password:$('#gPassword').value,programs,photo,address:$('#gAddress').value,experience:$('#gExp').value})});closeModal();toast(d.message)}catch(x){toast(x.message)}}
async function openStudentRegister(){let teachers=[];try{teachers=await api('/api/public/teachers')}catch{}modal(`<div class="section-head"><span class="eyebrow">PENDAFTARAN MURID</span><h2>Daftar Jadi Murid</h2></div><form onsubmit="registerStudent(event)" class="form-grid"><div><label>Nama Lengkap</label><input id="sName" required></div><div><label>Nomor WhatsApp</label><input id="sWa" required></div><div><label>Email</label><input id="sEmail" type="email" required></div><div><label>Password</label><input id="sPassword" type="password" minlength="8" required></div><div><label>Konfirmasi Password</label><input id="sPassword2" type="password" minlength="8" required></div><div><label>Program</label><select id="sProgram"><option value="TAHFIDZ">Tahfidz</option><option value="TAHSIN">Tahsin</option><option value="TAFSIR">Tafsir</option></select></div><div><label>Paket</label><select id="sPackage"><option>PAKET SORE</option><option>PAKET MALAM</option></select></div><div><label>Metode Pembelajaran</label><select id="sMode"><option value="ONLINE">ONLINE — Video Call via WhatsApp</option><option value="OFFLINE">OFFLINE — Tatap Muka</option></select></div><div><label>Pilihan Guru</label><select id="sTeacher"><option value="">Pilih guru</option>${teachers.map(t=>`<option value="${t.id}">${esc(t.name)} — ${esc(t.programs.join(', '))}</option>`).join('')}</select></div><div><label>Foto profil</label><input id="sPhoto" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="full"><label>Alamat</label><input id="sAddress"></div><div class="form-actions full"><button class="btn">DAFTAR</button></div><p class="hint full">Password digunakan untuk login setelah akun aktif.</p></form>`)}
async function registerStudent(e){e.preventDefault();if($('#sPassword').value!==$('#sPassword2').value)return toast('Konfirmasi password tidak sama.');try{const photo=await fileToDataUrl($('#sPhoto'));const d=await api('/api/register/murid',{method:'POST',body:JSON.stringify({name:$('#sName').value,whatsapp:$('#sWa').value,email:$('#sEmail').value,password:$('#sPassword').value,programs:[$('#sProgram').value],package:$('#sPackage').value,mode:$('#sMode').value,teacherId:$('#sTeacher').value,address:$('#sAddress').value,photo})});closeModal();toast(d.message)}catch(x){toast(x.message)}}
function showPublic(){document.body.classList.remove('dash-open');$('#publicApp').classList.remove('hidden');$('.site-header').classList.remove('hidden');$('footer').classList.remove('hidden');$('#dashboardApp').classList.add('hidden')}
function showDashboard(){document.body.classList.add('dash-open');$('#publicApp').classList.add('hidden');$('.site-header').classList.add('hidden');$('footer').classList.add('hidden');$('#dashboardApp').classList.remove('hidden');renderDashboardShell()}
function logout(){api('/api/logout',{method:'POST'}).catch(()=>{});state={user:null,token:'',settings:{},dashboard:null};localStorage.removeItem('bj_token');showPublic();location.hash='#home';toast('Anda telah keluar.')}
function renderDashboardShell(){const role=state.user.role;const nav=role==='ADMIN'?[
['home','Dashboard'],['profile','Profil Admin'],['registrations','Pendaftaran Guru/Murid'],['teachers','Guru'],['students','Murid'],['programs','Program'],['classes','Kelas'],['schedules','Jadwal'],['attendance','Absensi'],['progress','Progres'],['payments','Pembayaran'],['certificates','Sertifikat'],['notifications','Notifikasi'],['reports','Laporan'],['logs','Log Aktivitas'],['settings','Pengaturan']]:role==='GURU'?[['home','Dashboard'],['profile','Profil'],['requests','Permintaan Murid'],['students','Murid Saya'],['schedules','Jadwal'],['attendance','Absensi'],['tahfidz','Tahfidz'],['tahsin','Tahsin'],['tafsir','Tafsir'],['materials','Materi'],['notes','Catatan'],['assessment','Penilaian'],['certificates','Sertifikat'],['payments','Pembayaran'],['notifications','Notifikasi']]:[['home','Dashboard'],['profile','Profil'],['schedules','Jadwal'],['classes','Kelas'],['attendance','Absensi'],['progress','Progres Belajar'],['tahfidz','Tahfidz'],['tahsin','Tahsin'],['tafsir','Tafsir'],['materials','Materi'],['notes','Catatan Guru'],['payments','Pembayaran'],['certificates','Sertifikat'],['notifications','Notifikasi']];$('#dashboardApp').innerHTML=`<aside class="dash-side"><div class="dash-brand"><img src="/logo.png"><div><b>Baitul Jalal Ilmu Quran</b><small>${role}</small></div></div><div class="dash-nav">${nav.map(([k,l],i)=>`<button id="nav-${k}" onclick="dashPage('${k}')">${l}</button>`).join('')}<button onclick="logout()">Keluar</button></div></aside><section class="dash-main"><div class="dash-top"><div class="dash-title"><h1 id="dashTitle">Dashboard</h1><p>${esc(state.user.name)} · ${role}</p></div><div class="dash-actions"><button class="btn outline small" onclick="dashPage('notifications')">Notifikasi</button><button class="btn small" onclick="logout()">Logout</button></div></div><div id="dashContent"></div></section>`;dashPage('home')}
async function dashPage(page){$$('.dash-nav button').forEach(b=>b.classList.remove('active'));const n=$('#nav-'+page);if(n)n.classList.add('active');const title=page.replace(/^./,x=>x.toUpperCase());$('#dashTitle').textContent=title;const c=$('#dashContent');c.innerHTML='<div class="page-card"><div class="empty">Memuat...</div></div>';try{if(state.user.role==='ADMIN')await adminPage(page,c);else if(state.user.role==='GURU')await teacherPage(page,c);else await studentPage(page,c)}catch(e){c.innerHTML=`<div class="page-card"><div class="result-no"><b>Gagal memuat</b><p>${esc(e.message)}</p></div></div>`}}
function table(headers,rows){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||'<tr><td colspan="99" class="empty">Belum ada data.</td></tr>'}</tbody></table></div>`}
function status(s){const cls=['DITOLAK','NONAKTIF'].includes(s)?'bad':['MENUNGGU','MENUNGGU_VERIFIKASI','PERBAIKAN','MENUNGGU VERIFIKASI'].includes(s)?'warn':'';return `<span class="status ${cls}">${esc(s||'-')}</span>`}
async function adminPage(page,c){
 if(page==='home'){const d=await api('/api/dashboard');c.innerHTML=`<div class="kpis"><div class="kpi"><b>${d.stats.teachers}</b><span>TOTAL GURU AKTIF</span></div><div class="kpi"><b>${d.stats.students}</b><span>TOTAL MURID AKTIF</span></div><div class="kpi"><b>${d.stats.tahfidz}</b><span>TAHFIDZ</span></div><div class="kpi"><b>${d.stats.pending}</b><span>MENUNGGU VERIFIKASI</span></div></div>${table(['Waktu','Aktivitas','Aktor','Detail'],d.recentLogs.map(x=>`<tr><td>${esc(new Date(x.created_at).toLocaleString('id-ID'))}</td><td>${esc(x.action)}</td><td>${esc(x.actor_name||'-')}</td><td>${esc(x.detail)}</td></tr>`).join(''))}`;return}
 if(page==='profile'){c.innerHTML=`<div class="page-card"><h3>Profil Admin</h3><form onsubmit="saveProfile(event,'admin')" class="form-grid"><div><label>Nama</label><input id="pName" value="${esc(state.user.name)}"></div><div><label>Email</label><input value="${esc(state.user.email)}" disabled></div><div><label>Nomor WhatsApp</label><input id="pWa" value="${esc(state.user.whatsapp)}"></div><div><label>Foto</label><input id="pPhoto" type="file" accept="image/png,image/jpeg,image/webp"></div><div><label>Link website</label><input id="pWebsite" value="${esc(state.settings.website||location.origin)}"></div><div><label>Tanggal akun dibuat</label><input value="${esc(state.user.created_at)}" disabled></div><div class="form-actions full"><button class="btn">EDIT PROFIL</button></div></form></div><div class="page-card"><h3>Keamanan Akun</h3>${passwordForm()}</div>`;return}
 if(page==='registrations'){const d=await api('/api/admin/registrations');c.innerHTML=`<div class="page-card"><h3>Pendaftaran Guru</h3>${table(['Nama','WhatsApp','Email','Program','Status','Aksi'],d.teachers.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.whatsapp)}</td><td>${esc(x.email)}</td><td>${esc(parseList(x.programs).join(', '))}</td><td>${status(x.status)}</td><td><button class="btn small" onclick="teacherDecision(${x.id},'TERIMA')">TERIMA</button> <button class="btn small gold" onclick="teacherDecision(${x.id},'MINTA PERBAIKAN')">MINTA PERBAIKAN</button> <button class="btn small danger" onclick="teacherDecision(${x.id},'TOLAK')">TOLAK</button> <button class="btn small danger" onclick="deleteUser(${x.id},'registrations')">HAPUS</button></td></tr>`).join(''))}</div><div class="page-card"><h3>Pendaftaran Murid</h3>${table(['Nama','WhatsApp','Email','Program','Paket','Metode','Status','Aksi'],d.students.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.whatsapp)}</td><td>${esc(x.email)}</td><td>${esc(parseList(x.programs).join(', '))}</td><td>${esc(x.package)}</td><td>${esc(x.mode||'-')}</td><td>${status(x.status)}</td><td><button class="btn small" onclick="studentDecision(${x.id},'AKTIF')">TERIMA</button> <button class="btn small danger" onclick="studentDecision(${x.id},'DITOLAK')">TOLAK</button> <button class="btn small danger" onclick="deleteUser(${x.id},'registrations')">HAPUS</button></td></tr>`).join(''))}</div>`;return}
 if(page==='teachers'){const d=await api('/api/admin/users?role=GURU');c.innerHTML=`<div class="page-card"><div class="dash-top"><h3>Kelola Guru</h3><button class="btn small" onclick="openAddTeacher()">TAMBAH GURU MANUAL</button></div>${table(['Nama','WhatsApp','Email','Program','Status','Aksi'],d.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.whatsapp)}</td><td>${esc(x.email)}</td><td>${esc(parseList(x.programs).join(', '))}</td><td>${status(x.status)}</td><td><button class="btn small" onclick="setUserStatus(${x.id},'AKTIF')">Aktifkan</button> <button class="btn small gold" onclick="setUserStatus(${x.id},'NONAKTIF')">Nonaktifkan</button> <button class="btn small danger" onclick="deleteUser(${x.id})">HAPUS</button></td></tr>`).join(''))}</div>`;return}
 if(page==='students'){const d=await api('/api/admin/users?role=MURID'),t=await api('/api/admin/users?role=GURU');c.innerHTML=`<div class="page-card"><div class="section-head"><div><h3>Kelola Murid</h3><p>Tambah murid secara manual tanpa mengisi password.</p></div><button class="btn" onclick="openAddStudent()">TAMBAH MURID MANUAL</button></div>${table(['Nama','WhatsApp','Email','Program','Guru','Paket','Metode','Status','Aksi'],d.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.whatsapp)}</td><td>${esc(x.email)}</td><td>${esc(parseList(x.programs).join(', '))}</td><td><select onchange="moveStudent(${x.id},this.value)"><option value="">${x.teacher_id?'Ganti Guru':'Pilih Guru'}</option>${t.filter(g=>g.status==='AKTIF').map(g=>`<option value="${g.id}" ${x.teacher_id==g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></td><td>${esc(x.package||'-')}</td><td>${esc(x.learning_mode||'-')}</td><td>${status(x.status)}</td><td><button class="btn small" onclick="setUserStatus(${x.id},'AKTIF')">Aktifkan</button> <button class="btn small gold" onclick="setUserStatus(${x.id},'NONAKTIF')">Nonaktifkan</button> <button class="btn small danger" onclick="deleteUser(${x.id})">HAPUS</button></td></tr>`).join(''))}</div>`;return}
 if(page==='programs'){const d=await api('/api/admin/programs');c.innerHTML=`<div class="page-card"><h3>Program</h3><form onsubmit="addProgram(event)" class="form-grid"><div><label>Nama</label><input id="progName" placeholder="Program" required></div><div><label>Deskripsi</label><input id="progDesc"></div><div class="full"><label>Link Video Call WhatsApp</label><input id="progVideoLink" placeholder="Masukkan link video call WhatsApp untuk program ini"></div><div class="form-actions full"><button class="btn small">TAMBAH PROGRAM</button></div></form></div>${table(['ID','Program','Deskripsi','Link Video Call WhatsApp','Aksi'],d.map(x=>`<tr><td>${x.id}</td><td>${esc(x.name)}</td><td>${esc(x.description)}</td><td><input id="progLink_${x.id}" value="${esc(x.video_link||'')}" placeholder="Link video call WhatsApp"></td><td><button class="btn small" onclick="saveProgramVideoLink(${x.id})">SIMPAN LINK</button>${x.video_link?` <a class="btn small outline" href="${esc(x.video_link)}" target="_blank">BUKA</a>`:''} <button class="btn small danger" onclick="deleteAdminRecord('programs',${x.id},'programs')">HAPUS</button></td></tr>`).join(''))}`;return}
 if(page==='classes'){const [d,p,t]=await Promise.all([api('/api/admin/classes'),api('/api/admin/programs'),api('/api/admin/users?role=GURU')]);c.innerHTML=`<div class="page-card"><h3>Tambah Kelas</h3><form onsubmit="addClass(event)" class="form-grid"><div><label>Nama kelas</label><input id="className" required></div><div><label>Program</label><select id="classProgram">${p.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div><label>Guru</label><select id="classTeacher"><option value="">Belum ditentukan</option>${t.filter(x=>x.status==='AKTIF').map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div><label>Paket</label><select id="classPackage"><option>PAKET SORE</option><option>PAKET MALAM</option></select></div><div><label>Metode Pembelajaran</label><select id="classMode"><option value="ONLINE">ONLINE — Video Call via WhatsApp</option><option value="OFFLINE">OFFLINE — Tatap Muka</option></select></div><div><label>Link Video Call WhatsApp</label><input id="classLink" placeholder="https://chat.whatsapp.com/... atau tautan WhatsApp"></div><div><input id="classRoom"></div><div class="form-actions full"><button class="btn small">SIMPAN KELAS</button></div></form></div>${table(['Nama','Program','Guru','Paket','Metode','Link/Ruang','Status'],d.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.program_name||'-')}</td><td>${esc(x.teacher_name||'-')}</td><td>${esc(x.package)}</td><td>${esc(x.mode||'-')}</td><td>${x.link?`<a href="${esc(x.link)}" target="_blank">Video Call WhatsApp</a>`:esc(x.room||'-')}</td><td>${x.active?'AKTIF':'NONAKTIF'} <button class="btn small danger" onclick="deleteAdminRecord('classes',${x.id},'classes')">HAPUS</button></td></tr>`).join(''))}`;return}
 if(page==='schedules'){const [d,p,t,cl]=await Promise.all([api('/api/admin/schedules'),api('/api/admin/programs'),api('/api/admin/users?role=GURU'),api('/api/admin/classes')]);c.innerHTML=`<div class="page-card"><h3>Tambah Jadwal</h3>${scheduleForm('admin',p,t,cl)}</div>${table(['Program','Guru','Hari','Jam','Mode','Link/Ruang','Materi','Status'],d.map(x=>`<tr><td>${esc(x.program_name||'-')}</td><td>${esc(x.teacher_name||'-')}</td><td>${esc(x.day)}</td><td>${esc(x.start_time)}–${esc(x.end_time)}</td><td>${esc(x.mode)}</td><td>${esc(x.link||x.room||'-')}</td><td>${esc(x.material)}</td><td>${status(x.status)} <button class="btn small danger" onclick="deleteAdminRecord('schedules',${x.id},'schedules')">HAPUS</button></td></tr>`).join(''))}`;return}
 if(page==='attendance'){const d=await api('/api/admin/attendance');c.innerHTML=`<div class="page-card"><h3>Absensi</h3><p class="hint">Jadwal tidak otomatis berarti hadir. Guru harus menekan MULAI KELAS agar absensi Guru tercatat; Murid mencatat kehadiran saat kelas aktif.</p>${table(['Tanggal','Peran','Guru','Murid','Status','Metode','Masuk'],d.map(x=>`<tr><td>${esc(x.attendance_date)}</td><td>${esc(x.role)}</td><td>${esc(x.teacher_name||'-')}</td><td>${esc(x.student_name||'-')}</td><td>${status(x.status)}</td><td>${esc(x.method)}</td><td>${esc(x.check_in)} <button class="btn small danger" onclick="deleteAdminRecord('attendance',${x.id},'attendance')">HAPUS</button></td></tr>`).join(''))}</div>`;return}
 if(page==='progress'){const d=await api('/api/admin/progress');c.innerHTML=`<div class="page-card"><h3>Progres</h3>${table(['Tanggal','Murid','Guru','Program','Juz','Status','Nilai','Catatan'],d.map(x=>`<tr><td>${esc(x.learning_date)}</td><td>${esc(x.student_name)}</td><td>${esc(x.teacher_name||'-')}</td><td>${esc(x.program)}</td><td>${x.juz}</td><td>${status(x.status)}</td><td>${esc(x.score??'-')}</td><td>${esc(x.notes)} <button class="btn small danger" onclick="deleteAdminRecord('progress',${x.id},'progress')">HAPUS</button></td></tr>`).join(''))}</div>`;return}
 if(page==='payments'){const [d,s]=await Promise.all([api('/api/admin/payments'),api('/api/admin/settings')]);c.innerHTML=`<div class="page-card"><h3>Informasi Pembayaran</h3><form onsubmit="savePaymentSettings(event)" class="form-grid"><div><label>Nama bank/e-wallet</label><input id="payBank" value="${esc(s.payment_bank||'')}"></div><div><label>Nomor rekening/nomor akun</label><input id="payAccount" value="${esc(s.payment_account||'')}"></div><div><label>Atas nama</label><input id="payOwner" value="${esc(s.payment_owner||'')}"></div><div><label>QR pembayaran (gambar)</label><input id="payQr" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="form-actions full"><button class="btn small">SIMPAN INFORMASI PEMBAYARAN</button></div></form></div><div class="page-card"><h3>Bukti Pembayaran Murid</h3>${table(['Murid','Bukti Pembayaran','Status','Aksi'],d.map(x=>`<tr><td>${esc(x.student_name)}</td><td>${x.proof_path?`${privateFileButton(x.proof_path,'LIHAT BUKTI PEMBAYARAN')}`:'Belum ada bukti'}</td><td>${status(x.status)}</td><td><select onchange="paymentStatus(${x.id},this.value)"><option>${esc(x.status)}</option>${['BELUM BAYAR','MENUNGGU VERIFIKASI','SUDAH BAYAR','DITOLAK'].filter(z=>z!==x.status).map(z=>`<option>${z}</option>`).join('')}</select> <button class="btn small danger" onclick="deleteAdminRecord('payments',${x.id},'payments')">HAPUS</button></td></tr>`).join(''))}</div>`;return}
 if(page==='certificates'){const [d,students]=await Promise.all([api('/api/admin/certificates'),api('/api/admin/users?role=MURID')]);c.innerHTML=`<div class="page-card"><h3>Upload Sertifikat PDF</h3><p class="hint">Admin mengunggah PDF resmi yang sudah disiapkan lembaga, lalu menghubungkannya dengan akun Murid agar otomatis muncul di Dashboard Murid.</p><form onsubmit="uploadCertificate(event)" class="form-grid"><div><label>Pilih Murid</label><select id="certStudent" required><option value="">Pilih Murid</option>${students.filter(x=>x.status==='AKTIF').map(x=>`<option value="${x.id}">${esc(x.name)} — ${esc(x.program||'-')}</option>`).join('')}</select></div><div><label>File Sertifikat PDF</label><input id="certPdf" type="file" accept="application/pdf" required></div><div class="form-actions full"><button class="btn">UPLOAD & TERBITKAN KE DASHBOARD MURID</button></div></form></div>${table(['Murid','Nomor','Program','Tanggal','File PDF','Aksi'],d.map(x=>`<tr><td>${esc(x.student_name||'-')}</td><td>${esc(x.certificate_number||'-')}</td><td>${esc(x.program||'-')}</td><td>${esc(x.issue_date||new Date(x.created_at).toLocaleDateString('id-ID'))}</td><td>${x.pdf_path?`<a href="${esc(x.pdf_path)}" target="_blank">Buka PDF</a>`:'-'}</td><td><button class="btn small danger" onclick="deleteCertificate(${x.id})">HAPUS</button></td></tr>`).join(''))}`;return}
 if(page==='notifications'){const d=await api('/api/admin/notifications');c.innerHTML=`<div class="page-card"><h3>Notifikasi</h3>${table(['Waktu','Pengguna','Judul','Pesan','Jenis','Status'],d.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.user_name||'Admin')}</td><td>${esc(x.title)}</td><td>${esc(x.message)}</td><td>${esc(x.type)}</td><td>${x.is_read?'Dibaca':'Belum dibaca'} <button class="btn small danger" onclick="deleteAdminRecord('notifications',${x.id},'notifications')">HAPUS</button></td></tr>`).join(''))}</div>`;return}
 if(page==='reports'){const d=await api('/api/admin/reports');c.innerHTML=`<div class="page-card"><h3>Laporan</h3><div class="split"><div><h3>Status Guru</h3>${table(['Status','Jumlah'],d.teachers.map(x=>`<tr><td>${status(x.status)}</td><td>${x.c}</td></tr>`).join(''))}</div><div><h3>Status Murid</h3>${table(['Status','Jumlah'],d.students.map(x=>`<tr><td>${status(x.status)}</td><td>${x.c}</td></tr>`).join(''))}</div></div><p>Total sertifikat: <b>${d.certificates}</b></p></div>`;return}
 if(page==='logs'){const d=await api('/api/admin/logs');c.innerHTML=`<div class="page-card"><div class="section-head"><h3>Riwayat Aktivitas</h3><button class="btn small danger" onclick="clearActivityLogs()">HAPUS AKTIVITAS</button></div>${table(['Waktu','Aktor','Aksi','Target','Detail','Aksi'],d.map(x=>`<tr><td>${esc(new Date(x.created_at).toLocaleString('id-ID'))}</td><td>${esc(x.actor_name||'-')}</td><td>${esc(x.action)}</td><td>${esc(x.target_type)} #${esc(x.target_id||'-')}</td><td>${esc(x.detail)}</td><td><button class="btn small danger" onclick="deleteActivity(${x.id})">HAPUS AKTIVITAS</button></td></tr>`).join(''))}</div>`;return}
 if(page==='settings'){const s=await api('/api/admin/settings');c.innerHTML=`<div class="page-card"><h3>Pengaturan</h3><form onsubmit="saveSettings(event)" class="form-grid"><div><label>Nama Website</label><input id="set_site_name" value="${esc(s.site_name||'Baitul Jalal Ilmu Quran')}"></div><div><label>WhatsApp</label><input id="set_whatsapp" value="${esc(s.whatsapp||'')}"></div><div><label>Website</label><input id="set_website" value="${esc(s.website||location.origin)}"></div><div class="full"><label>Alamat</label><textarea id="set_address">${esc(s.address||'')}</textarea></div><div class="full social-settings-grid"><div class="social-setting"><label>Facebook</label><input id="set_facebook" type="url" placeholder="https://facebook.com/..." value="${esc(s.social_facebook||'')}"></div><div class="social-setting"><label>Instagram</label><input id="set_instagram" type="url" placeholder="https://instagram.com/..." value="${esc(s.social_instagram||'')}"></div><div class="social-setting"><label>YouTube</label><input id="set_youtube" type="url" placeholder="https://youtube.com/..." value="${esc(s.social_youtube||'')}"></div><div class="social-setting"><label>TikTok</label><input id="set_tiktok" type="url" placeholder="https://tiktok.com/@..." value="${esc(s.social_tiktok||'')}"></div></div><div class="form-actions full"><button class="btn">SIMPAN PENGATURAN</button> <button type="button" class="btn small danger" onclick="clearAdminSettings()">HAPUS</button></div></form></div>`;return}
}
function parseList(x){if(!x)return[];try{const a=JSON.parse(x);return Array.isArray(a)?a:[x]}catch{return String(x).split(',').filter(Boolean)}}
function today(){return new Date().toISOString().slice(0,10)}
async function teacherDecision(id,decision){try{await api('/api/admin/teacher-decision',{method:'POST',body:JSON.stringify({id,decision})});toast('Keputusan tersimpan.');dashPage('registrations')}catch(e){toast(e.message)}}
async function studentDecision(id,status){try{await api('/api/admin/student-decision',{method:'POST',body:JSON.stringify({id,status})});toast('Status murid diperbarui.');dashPage('registrations')}catch(e){toast(e.message)}}
async function deleteUser(id,returnPage='teachers'){if(!confirm('Hapus data ini secara permanen? Tindakan ini tidak dapat dibatalkan.'))return;try{await api('/api/admin/delete-user',{method:'POST',body:JSON.stringify({id})});toast('Data dihapus.');dashPage(returnPage)}catch(e){toast(e.message)}}
async function deleteAdminRecord(type,id,page){if(!confirm('Hapus data ini secara permanen? Tindakan ini tidak dapat dibatalkan.'))return;try{await api('/api/admin/delete-record',{method:'POST',body:JSON.stringify({type,id})});toast('Data dihapus.');dashPage(page)}catch(e){toast(e.message)}}
async function clearAdminSettings(){if(!confirm('Hapus semua pengaturan yang tersimpan?'))return;try{await api('/api/admin/settings/delete',{method:'POST'});toast('Pengaturan dihapus.');await loadPublicSettings();renderSocialLinks();dashPage('settings')}catch(e){toast(e.message)}}
async function setUserStatus(id,status){if(status==='DITOLAK'&&!confirm('Tindakan ini akan menonaktifkan akun. Lanjutkan?'))return;try{await api('/api/admin/user-status',{method:'POST',body:JSON.stringify({id,status})});toast('Status diperbarui.');dashPage('teachers')}catch(e){toast(e.message)}}
async function moveStudent(id,teacherId){if(!teacherId)return;try{await api('/api/admin/move-student',{method:'POST',body:JSON.stringify({studentId:id,teacherId})});toast('Guru murid berhasil dipindahkan.');dashPage('students')}catch(e){toast(e.message)}}
function openAddStudent(){api('/api/admin/users?role=GURU').then(teachers=>{modal(`<div class="section-head"><span class="eyebrow">ADMIN</span><h2>Tambah Murid Manual</h2></div><form onsubmit="addStudent(event)" class="form-grid"><div><label>Nama Lengkap</label><input id="amName" required></div><div><label>WhatsApp</label><input id="amWa" required></div><div><label>Email</label><input id="amEmail" type="email" required></div><div><label>Program</label><select id="amProgram"><option value="TAHFIDZ">Tahfidz</option><option value="TAHSIN">Tahsin</option><option value="TAFSIR">Tafsir</option></select></div><div><label>Paket</label><select id="amPackage"><option>PAKET SORE</option><option>PAKET MALAM</option></select></div><div><label>Metode</label><select id="amMode"><option value="ONLINE">ONLINE — Video Call via WhatsApp</option><option value="OFFLINE">OFFLINE — Tatap Muka</option></select></div><div><label>Pilihan Guru</label><select id="amTeacher"><option value="">Pilih Guru</option>${teachers.filter(t=>t.status==='AKTIF').map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="full"><div><label>Alamat</label><textarea id="amAddress"></textarea></div></div><div class="form-actions full"><button class="btn">BUAT AKUN MURID</button></div></form>`)}).catch(e=>toast(e.message))}
async function addStudent(e){e.preventDefault();try{const d=await api('/api/admin/add-student',{method:'POST',body:JSON.stringify({name:$('#amName').value,whatsapp:$('#amWa').value,email:$('#amEmail').value,program:$('#amProgram').value,package:$('#amPackage').value,mode:$('#amMode').value,teacherId:$('#amTeacher').value,address:$('#amAddress').value})});closeModal();toast(d.message||'Murid berhasil ditambahkan.');dashPage('students')}catch(x){toast(x.message)}}
function openAddTeacher(){modal(`<div class="section-head"><span class="eyebrow">ADMIN</span><h2>Tambah Guru Manual</h2></div><form onsubmit="addTeacher(event)" class="form-grid"><div><label>Nama Lengkap</label><input id="agName" required></div><div><label>Nomor WhatsApp</label><input id="agWa" required></div><div><label>Email</label><input id="agEmail" type="email" required></div><div><label>Program</label><input id="agProg" placeholder="TAHFIDZ, TAHSIN, TAFSIR"></div><div><label>Status</label><select id="agStatus"><option>AKTIF</option><option>NONAKTIF</option></select></div><div class="form-actions full"><button class="btn">BUAT AKUN</button></div></form>`)}
async function addTeacher(e){e.preventDefault();try{const d=await api('/api/admin/add-teacher',{method:'POST',body:JSON.stringify({name:$('#agName').value,whatsapp:$('#agWa').value,email:$('#agEmail').value,programs:$('#agProg').value,status:$('#agStatus').value})});closeModal();toast(d.message||'Akun Guru berhasil dibuat.');dashPage('teachers')}catch(x){toast(x.message)}}
async function saveProgramVideoLink(id){try{await api('/api/admin/programs/link',{method:'POST',body:JSON.stringify({id,videoLink:$('#progLink_'+id).value})});toast('Link video call program disimpan.');dashPage('programs')}catch(x){toast(x.message)}}
async function addProgram(e){e.preventDefault();try{await api('/api/admin/programs',{method:'POST',body:JSON.stringify({name:$('#progName').value,description:$('#progDesc').value,videoLink:$('#progVideoLink').value})});toast('Program ditambahkan.');dashPage('programs')}catch(x){toast(x.message)}}
async function addClass(e){e.preventDefault();try{await api('/api/admin/classes',{method:'POST',body:JSON.stringify({name:$('#className').value,programId:$('#classProgram').value,teacherId:$('#classTeacher').value,package:$('#classPackage').value,mode:$('#classMode').value,link:$('#classLink').value,room:$('#classRoom').value})});toast('Kelas disimpan.');dashPage('classes')}catch(x){toast(x.message)}}
function scheduleForm(kind,p,t,cl){return `<form onsubmit="addSchedule(event,'${kind}')" class="form-grid"><div><label>Program</label><select id="schProgram" onchange="fillProgramVideoLink()">${p.map(x=>`<option value="${x.id}" data-video-link="${esc(x.video_link||'')}">${esc(x.name)}</option>`).join('')}</select></div><div><label>Guru</label><select id="schTeacher">${t.filter(x=>x.status==='AKTIF').map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div><label>Kelas</label><select id="schClass"><option value="">Tanpa kelas</option>${cl.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div><label>Hari</label><select id="schDay"><option>Senin</option><option>Selasa</option><option>Rabu</option><option>Kamis</option><option>Jumat</option><option>Sabtu</option><option>Minggu</option></select></div><div><label>Jam mulai</label><input id="schStart" type="time" required></div><div><label>Jam selesai</label><input id="schEnd" type="time" required></div><div><label>Online/Offline</label><select id="schMode" onchange="toggleScheduleFields()"><option>ONLINE</option><option>OFFLINE</option></select></div><div><label>Link Video Call WhatsApp</label><input id="schLink" placeholder="Bagikan link video call WhatsApp"></div><div><label>Ruangan jika offline</label><input id="schRoom" placeholder="Tempat tatap muka"></div><div class="full"><p class="hint">ONLINE = video call via WhatsApp menggunakan link yang dibagikan. OFFLINE = pembelajaran langsung tatap muka.</p></div><div><label>Materi</label><input id="schMaterial"></div><div class="form-actions full"><button class="btn small">TAMBAH JADWAL</button></div></form><script>setTimeout(()=>{fillProgramVideoLink();toggleScheduleFields()},0)</script>`}
function fillProgramVideoLink(){const p=$('#schProgram'),link=$('#schLink'),mode=$('#schMode');if(!p||!link)return;const o=p.options[p.selectedIndex];const v=o?.dataset?.videoLink||'';if(v){link.value=v;if(mode)mode.value='ONLINE';}else if(!link.value||link.dataset.autoFilled==='1'){link.value='';}link.dataset.autoFilled=v?'1':'0';toggleScheduleFields()}
function toggleScheduleFields(){const mode=$('#schMode');const link=$('#schLink');const room=$('#schRoom');if(!mode||!link||!room)return;const online=mode.value==='ONLINE';link.required=online;room.required=!online;link.disabled=!online;room.disabled=online;if(online)room.value='';else link.value='';}
async function addSchedule(e,kind){e.preventDefault();try{await api(kind==='admin'?'/api/admin/schedules':'/api/teacher/schedules',{method:'POST',body:JSON.stringify({programId:$('#schProgram').value,teacherId:$('#schTeacher').value,classId:$('#schClass').value,day:$('#schDay').value,startTime:$('#schStart').value,endTime:$('#schEnd').value,mode:$('#schMode').value,link:$('#schLink').value,room:$('#schRoom').value,material:$('#schMaterial').value})});toast('Jadwal disimpan.');dashPage('schedules')}catch(x){toast(x.message)}}
async function savePaymentSettings(e){e.preventDefault();try{const qr=await fileToDataUrl($('#payQr'));await api('/api/admin/payment-settings',{method:'POST',body:JSON.stringify({payment_bank:$('#payBank').value,payment_account:$('#payAccount').value,payment_owner:$('#payOwner').value,payment_qr:qr})});toast('Informasi pembayaran diperbarui.');dashPage('payments')}catch(x){toast(x.message)}}
async function paymentStatus(id,status){try{await api('/api/admin/payment-status',{method:'POST',body:JSON.stringify({id,status})});toast('Status pembayaran diperbarui.');dashPage('payments')}catch(x){toast(x.message)}}
async function uploadCertificate(e){e.preventDefault();try{const pdf=await fileToDataUrl($('#certPdf'));await api('/api/admin/certificates',{method:'POST',body:JSON.stringify({pdf,studentId:Number($('#certStudent').value)})});toast('Sertifikat PDF berhasil diunggah.');dashPage('certificates')}catch(x){toast(x.message)}}
async function deleteCertificate(id){if(!confirm('Hapus sertifikat ini?'))return;try{await api('/api/admin/certificates/delete',{method:'POST',body:JSON.stringify({id})});toast('Sertifikat dihapus.');dashPage('certificates')}catch(x){toast(x.message)}}
function passwordForm(){return `<form onsubmit="changePassword(event)" class="form-grid"><div><label>Password sekarang</label><input id="pwCurrent" type="password" required></div><div><label>Password baru</label><input id="pwNew" type="password" minlength="8" required></div><div><label>Konfirmasi password baru</label><input id="pwNew2" type="password" minlength="8" required></div><div class="form-actions full"><button class="btn small">UBAH PASSWORD</button></div></form>`}
async function changePassword(e){e.preventDefault();if($('#pwNew').value!==$('#pwNew2').value)return toast('Konfirmasi password tidak sama.');try{await api('/api/change-password',{method:'POST',body:JSON.stringify({currentPassword:$('#pwCurrent').value,newPassword:$('#pwNew').value})});toast('Password berhasil diubah.')}catch(x){toast(x.message)}}
async function deleteActivity(id){try{await api('/api/admin/logs/delete',{method:'POST',body:JSON.stringify({id})});toast('Aktivitas dihapus.');dashPage('logs')}catch(x){toast(x.message)}}
async function clearActivityLogs(){if(!confirm('Hapus semua riwayat aktivitas?'))return;try{const d=await api('/api/admin/logs');for(const x of d) await api('/api/admin/logs/delete',{method:'POST',body:JSON.stringify({id:x.id})});toast('Riwayat aktivitas dihapus.');dashPage('logs')}catch(x){toast(x.message)}}
async function saveSettings(e){e.preventDefault();try{await api('/api/admin/settings',{method:'POST',body:JSON.stringify({site_name:$('#set_site_name').value,whatsapp:$('#set_whatsapp').value,website:$('#set_website').value,address:$('#set_address').value,social_facebook:$('#set_facebook').value,social_instagram:$('#set_instagram').value,social_youtube:$('#set_youtube').value,social_tiktok:$('#set_tiktok').value})});toast('Pengaturan disimpan.');await loadPublicSettings();renderSocialLinks()}catch(x){toast(x.message)}}
async function saveProfile(e,role){e.preventDefault();try{const photo=await fileToDataUrl($('#pPhoto'));const endpoint=role==='admin'?'/api/admin/profile':role==='guru'?'/api/teacher/profile':'/api/student/profile';const body={name:$('#pName').value,whatsapp:$('#pWa').value,photo};if(role==='guru'){body.address=$('#pAddress').value;body.experience=$('#pExp').value;body.programs=$$('#pPrograms input:checked').map(x=>x.value)}if(role==='murid')body.address=$('#pAddress').value;await api(endpoint,{method:'POST',body:JSON.stringify(body)});state.user=(await api('/api/me')).user;toast('Profil diperbarui.');dashPage('profile')}catch(x){toast(x.message)}}
async function teacherPage(page,c){
 if(page==='home'){const d=await api('/api/dashboard');c.innerHTML=`<div class="kpis"><div class="kpi"><b>${d.stats.total}</b><span>TOTAL MURID</span></div><div class="kpi"><b>${d.stats.active}</b><span>MURID AKTIF</span></div><div class="kpi"><b>${d.stats.schedules}</b><span>JADWAL AKTIF</span></div><div class="kpi"><b>${d.stats.attendance}</b><span>KEHADIRAN HARI INI</span></div></div><div class="page-card"><h3>Profil Guru</h3><p>${esc(state.user.name)} · ${esc(state.user.email)} · ${esc(state.user.whatsapp)}</p><p>Program: ${parseList(state.user.programs).map(x=>`<span class="chip">${esc(x)}</span>`).join(' ')}</p></div>`;return}
 if(page==='profile'){c.innerHTML=`<div class="page-card"><h3>Profil Guru</h3><form onsubmit="saveProfile(event,'guru')" class="form-grid"><div><label>Nama</label><input id="pName" value="${esc(state.user.name)}"></div><div><label>WhatsApp</label><input id="pWa" value="${esc(state.user.whatsapp)}"></div><div><label>Foto</label><input id="pPhoto" type="file" accept="image/png,image/jpeg,image/webp"></div><div><label>Alamat</label><input id="pAddress" value="${esc(state.user.address)}"></div><div class="full"><label>Pengalaman</label><textarea id="pExp">${esc(state.user.experience)}</textarea></div><div id="pPrograms" class="full"><label>Program</label><div class="chips">${['TAHFIDZ','TAHSIN','TAFSIR'].map(x=>`<label><input type="checkbox" value="${x}" ${parseList(state.user.programs).includes(x)?'checked':''}> ${x}</label>`).join('')}</div></div><div class="form-actions full"><button class="btn">SIMPAN PROFIL</button></div></form></div><div class="page-card"><p class="hint">Login Guru menggunakan email dan password.</p></div>`;return}
 if(page==='requests'){const d=await api('/api/teacher/requests');c.innerHTML=`<div class="page-card"><h3>Permintaan Murid</h3>${table(['Murid','WhatsApp','Email','Program','Paket','Metode','Aksi'],d.map(x=>`<tr><td>${esc(x.student_name)}</td><td>${esc(x.whatsapp)}</td><td>${esc(x.email)}</td><td>${esc(x.program)}</td><td>${esc(x.package)}</td><td>${esc(x.mode||'-')}</td><td><button class="btn small" onclick="requestDecision(${x.id},'TERIMA')">TERIMA MURID</button> <button class="btn small danger" onclick="requestDecision(${x.id},'TOLAK')">TOLAK</button></td></tr>`).join(''))}</div>`;return}
 if(page==='students'){const d=await api('/api/teacher/students');c.innerHTML=`<div class="page-card"><h3>Murid Saya</h3>${table(['Nama','WhatsApp','Email','Program','Paket','Status','Aksi'],d.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.whatsapp)}</td><td>${esc(x.email)}</td><td>${esc(parseList(x.programs).join(', '))}</td><td>${esc(x.package)}</td><td>${status(x.status)}</td><td><button class="btn small" onclick="studentProgress(${x.id})">PROGRES</button> <button class="btn small outline" onclick="studentNote(${x.id})">CATATAN</button></td></tr>`).join(''))}</div>`;return}
 if(page==='schedules'){const [d,p,cl]=await Promise.all([api('/api/teacher/schedules'),api('/api/public/programs'),api('/api/admin/classes').catch(()=>[]) ]);c.innerHTML=`<div class="page-card"><h3>Jadwal</h3>${scheduleFormTeacher(p,cl)}<hr>${table(['Hari','Jam','Mode','Link/Ruang','Materi','Status','Aksi'],d.map(x=>`<tr><td>${esc(x.day)}</td><td>${esc(x.start_time)}–${esc(x.end_time)}</td><td>${esc(x.mode)}</td><td>${esc(x.link||x.room||'-')}</td><td>${esc(x.material)}</td><td>${status(x.status)}</td><td><button class="btn small" onclick="startClass(${x.id})">MULAI KELAS</button></td></tr>`).join(''))}</div>`;return}
 if(page==='attendance'){const d=await api('/api/teacher/students');const s=await api('/api/teacher/schedules');c.innerHTML=`<div class="page-card"><h3>Absensi Murid</h3><form onsubmit="markAttendance(event)" class="form-grid"><div><label>Jadwal</label><select id="attSchedule">${s.map(x=>`<option value="${x.id}">${esc(x.day)} ${esc(x.start_time)}–${esc(x.end_time)}</option>`).join('')}</select></div><div><label>Murid</label><select id="attStudent">${d.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div><label>Status</label><select id="attStatus"><option>HADIR</option><option>IZIN</option><option>SAKIT</option><option>ALPHA</option></select></div><div><label>Metode</label><input id="attMethod" value="GURU"></div><div class="form-actions full"><button class="btn">CATAT ABSENSI</button></div></form><p class="hint">Untuk Guru: gunakan MULAI KELAS pada Jadwal. Sistem mencatat waktu masuk saat kelas dibuka.</p></div>`;return}
 if(['tahfidz','tahsin','tafsir','assessment'].includes(page)){const d=await api('/api/teacher/students');c.innerHTML=`<div class="page-card"><h3>${page==='assessment'?'Penilaian':page.toUpperCase()}</h3><form onsubmit="saveProgress(event,'${page==='assessment'?'TAHFIDZ':page.toUpperCase()}')" class="form-grid"><div><label>Murid</label><select id="prStudent">${d.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div><label>Tanggal pembelajaran</label><input id="prDate" type="date" value="${today()}"></div>${page==='tahfidz'||page==='assessment'?`<div><label>Juz (1–30)</label><select id="prJuz">${Array.from({length:30},(_,i)=>`<option>${i+1}</option>`).join('')}</select></div><div><label>Status</label><select id="prStatus"><option>BELUM DIMULAI</option><option>DALAM PROSES</option><option>SELESAI</option></select></div>`:`<div><label>Status</label><select id="prStatus"><option>BAIK</option><option>CUKUP</option><option>PERLU DIPERBAIKI</option></select></div>`}<div><label>Nilai/progres</label><input id="prScore" type="number" min="0" max="100"></div>${page==='tahsin'?`<div><label>Makharijul huruf</label><input id="prMakharij"></div><div><label>Tajwid</label><input id="prTajwid"></div><div><label>Kelancaran</label><input id="prFluency"></div><div><label>Panjang pendek</label><input id="prLength"></div>`:''}${page==='tafsir'?`<div><label>Materi</label><input id="prMaterial"></div><div><label>Pemahaman</label><input id="prUnderstanding"></div>`:''}<div class="full"><label>Catatan guru</label><textarea id="prNotes"></textarea></div><div class="form-actions full"><button class="btn">SIMPAN</button></div></form><div id="recentProgress"></div></div>`;return}
 if(page==='materials'){c.innerHTML=`<div class="page-card"><h3>Materi</h3><form onsubmit="addMaterial(event)" class="form-grid"><div><label>Judul</label><input id="matTitle" required></div><div><label>Program</label><select id="matProgram"><option>TAHFIDZ</option><option>TAHSIN</option><option>TAFSIR</option></select></div><div class="full"><label>Deskripsi</label><textarea id="matDesc"></textarea></div><div><label>URL/file path materi</label><input id="matPath" placeholder="/uploads/... atau tautan resmi"></div><div class="form-actions full"><button class="btn">TAMBAH MATERI</button></div></form></div>`;return}
 if(page==='notes'){const d=await api('/api/teacher/students');c.innerHTML=`<div class="page-card"><h3>Catatan Guru</h3><form onsubmit="addNote(event)" class="form-grid"><div><label>Murid</label><select id="noteStudent">${d.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="full"><label>Catatan</label><textarea id="noteContent" required></textarea></div><div class="form-actions full"><button class="btn">SIMPAN CATATAN</button></div></form></div>`;return}
 if(page==='payments'){const [d,s]=await Promise.all([api('/api/teacher/payments'),api('/api/teacher/payment-settings')]);c.innerHTML=`<div class="page-card"><h3>Informasi Pembayaran</h3><form onsubmit="saveTeacherPaymentSettings(event)" class="form-grid"><div><label>NAMA REKENING/E-WALLET</label><input id="tpBank" value="${esc(s.payment_bank||'')}" placeholder="Contoh: Bank Syariah Indonesia / DANA" required></div><div><label>NOMOR REKENING</label><input id="tpAccount" value="${esc(s.payment_account||'')}" placeholder="Masukkan nomor rekening/nomor akun" required></div><div><label>ATAS NAMA</label><input id="tpOwner" value="${esc(s.payment_owner||'')}" placeholder="Nama pemilik rekening/e-wallet" required></div><div class="form-actions full"><button class="btn small">SIMPAN INFORMASI PEMBAYARAN</button></div></form></div><div class="page-card"><h3>Bukti Pembayaran Murid</h3>${table(['Murid','Bukti Pembayaran','Status'],d.map(x=>`<tr><td>${esc(x.student_name)}</td><td>${x.proof_path?`${privateFileButton(x.proof_path,'LIHAT BUKTI PEMBAYARAN')}`:'Belum ada bukti'}</td><td>${status(x.status)}</td></tr>`).join(''))}</div>`;return}
 if(page==='certificates'){const d=await api('/api/teacher/certificates');c.innerHTML=`<div class="page-card"><h3>Sertifikat Murid Saya</h3><p class="hint">Guru tidak membuat PDF otomatis. Sertifikat resmi diunggah dan diterbitkan oleh Admin sesuai rancangan.</p>${table(['Nomor','Murid','Program','Tanggal','PDF'],d.map(x=>`<tr><td>${esc(x.certificate_number)}</td><td>${esc(x.student_name)}</td><td>${esc(x.program)}</td><td>${esc(x.issue_date)}</td><td>${privateFileButton(x.pdf_path,'Buka PDF')}</td></tr>`).join(''))}</div>`;return}
 if(page==='notifications'){const d=await api('/api/notifications');c.innerHTML=`<div class="page-card"><h3>Notifikasi</h3>${table(['Waktu','Judul','Pesan','Jenis','Status'],d.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.title)}</td><td>${esc(x.message)}</td><td>${esc(x.type)}</td><td>${x.is_read?'Dibaca':`<button class="btn small" onclick="readNotification(${x.id})">Tandai dibaca</button>`}</td></tr>`).join(''))}</div>`;return}
}
function scheduleFormTeacher(p,cl){return scheduleForm('teacher',p,[[state.user.id,state.user.name]].map(x=>({id:x[0],name:x[1],status:'AKTIF'})),cl)}
async function requestDecision(id,decision){try{await api('/api/teacher/request-decision',{method:'POST',body:JSON.stringify({id,decision})});toast('Keputusan tersimpan.');dashPage('requests')}catch(e){toast(e.message)}}
async function startClass(id){try{const d=await api('/api/teacher/start-class',{method:'POST',body:JSON.stringify({scheduleId:id})});toast(d.message);dashPage('schedules')}catch(e){toast(e.message)}}
async function markAttendance(e){e.preventDefault();try{await api('/api/teacher/attendance',{method:'POST',body:JSON.stringify({scheduleId:$('#attSchedule').value,studentId:$('#attStudent').value,status:$('#attStatus').value,method:$('#attMethod').value})});toast('Absensi tercatat.')}catch(x){toast(x.message)}}
async function saveProgress(e,program){e.preventDefault();try{await api('/api/teacher/progress',{method:'POST',body:JSON.stringify({studentId:$('#prStudent').value,program,juz:$('#prJuz')?.value||0,status:$('#prStatus').value,makharij:$('#prMakharij')?.value||'',tajwid:$('#prTajwid')?.value||'',fluency:$('#prFluency')?.value||'',lengthRule:$('#prLength')?.value||'',material:$('#prMaterial')?.value||'',understanding:$('#prUnderstanding')?.value||'',score:$('#prScore').value,notes:$('#prNotes').value,learningDate:$('#prDate').value})});toast('Progres tersimpan.')}catch(x){toast(x.message)}}
async function addNote(e){e.preventDefault();try{await api('/api/teacher/note',{method:'POST',body:JSON.stringify({studentId:$('#noteStudent').value,content:$('#noteContent').value})});toast('Catatan disimpan.')}catch(x){toast(x.message)}}
async function addMaterial(e){e.preventDefault();try{await api('/api/teacher/material',{method:'POST',body:JSON.stringify({title:$('#matTitle').value,description:$('#matDesc').value,program:$('#matProgram').value,filePath:$('#matPath').value})});toast('Materi ditambahkan.')}catch(x){toast(x.message)}}
async function studentProgress(id){const d=await api('/api/teacher/progress?studentId='+id);modal(`<div class="section-head"><span class="eyebrow">PROGRES</span><h2>Riwayat Progres</h2></div>${table(['Tanggal','Program','Juz','Status','Nilai','Catatan'],d.map(x=>`<tr><td>${esc(x.learning_date)}</td><td>${esc(x.program)}</td><td>${x.juz}</td><td>${status(x.status)}</td><td>${esc(x.score??'-')}</td><td>${esc(x.notes)}</td></tr>`).join(''))}`)}
async function studentNote(id){modal(`<div class="section-head"><h2>Catatan Guru</h2></div><form onsubmit="submitQuickNote(event,${id})"><textarea id="quickNote" required></textarea><div class="form-actions"><button class="btn">SIMPAN</button></div></form>`)}
async function submitQuickNote(e,id){e.preventDefault();try{await api('/api/teacher/note',{method:'POST',body:JSON.stringify({studentId:id,content:$('#quickNote').value})});closeModal();toast('Catatan disimpan.')}catch(x){toast(x.message)}}
async function saveTeacherPaymentSettings(e){e.preventDefault();try{await api('/api/teacher/payment-settings',{method:'POST',body:JSON.stringify({payment_bank:$('#tpBank').value,payment_account:$('#tpAccount').value,payment_owner:$('#tpOwner').value})});toast('Informasi pembayaran berhasil disimpan.');dashPage('payments')}catch(x){toast(x.message)}}
async function teacherPageExtras(){return}
async function studentPage(page,c){
 if(page==='home'){const d=await api('/api/dashboard');c.innerHTML=`<div class="kpis"><div class="kpi"><b>${esc(state.user.name)}</b><span>NAMA MURID</span></div><div class="kpi"><b>${d.stats.schedules}</b><span>JADWAL AKTIF</span></div><div class="kpi"><b>${d.stats.attendance}</b><span>KEHADIRAN</span></div><div class="kpi"><b>${d.stats.certificates}</b><span>SERTIFIKAT</span></div></div><div class="page-card"><h3>Guru</h3><p>${esc(d.stats.teacher?.name||'Belum ditetapkan')} ${d.stats.teacher?`· ${esc(d.stats.teacher.whatsapp||'')}`:''}</p></div>`;return}
 if(page==='profile'){c.innerHTML=`<div class="page-card"><h3>Profil Murid</h3><form onsubmit="saveProfile(event,'murid')" class="form-grid"><div><label>Nama</label><input id="pName" value="${esc(state.user.name)}"></div><div><label>Email</label><input value="${esc(state.user.email)}" disabled></div><div><label>WhatsApp</label><input id="pWa" value="${esc(state.user.whatsapp)}"></div><div><label>Foto</label><input id="pPhoto" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="full"><label>Alamat</label><textarea id="pAddress">${esc(state.user.address)}</textarea></div><div class="form-actions full"><button class="btn">SIMPAN PROFIL</button></div></form></div><div class="page-card"><p class="hint">Login Murid menggunakan email dan password.</p></div>`;return}
 if(page==='schedules'||page==='classes'){const d=await api('/api/student/schedules');c.innerHTML=`<div class="page-card"><h3>${page==='classes'?'Kelas':'Jadwal Saya'}</h3>${table(['Program','Guru','Hari','Jam','Mode','Link/Ruang','Materi','Status','Aksi'],d.map(x=>`<tr><td>${esc(x.program_name||'-')}</td><td>${esc(x.teacher_name||'-')}</td><td>${esc(x.day)}</td><td>${esc(x.start_time)}–${esc(x.end_time)}</td><td>${esc(x.mode)}</td><td>${x.mode==='ONLINE'&&x.link?`<a href="${esc(x.link)}" target="_blank">VIDEO CALL WHATSAPP</a>`:esc(x.room||'Tatap muka')}</td><td>${esc(x.material)}</td><td>${status(x.status)}</td><td><button class="btn small" onclick="studentAttend(${x.id})">HADIR</button></td></tr>`).join(''))}</div>`;return}
 if(page==='attendance'){const d=await api('/api/student/schedules');c.innerHTML=`<div class="page-card"><h3>Absensi</h3><p class="hint">Saat kelas aktif, tekan HADIR. Sistem mencatat waktu masuk berdasarkan akun.</p>${table(['Hari','Jam','Program','Guru','Aksi'],d.map(x=>`<tr><td>${esc(x.day)}</td><td>${esc(x.start_time)}–${esc(x.end_time)}</td><td>${esc(x.program_name||'-')}</td><td>${esc(x.teacher_name||'-')}</td><td><button class="btn small" onclick="studentAttend(${x.id})">HADIR</button></td></tr>`).join(''))}</div>`;return}
 if(page==='progress'||page==='tahfidz'||page==='tahsin'||page==='tafsir'){const d=await api('/api/student/progress');if(page==='tahfidz'){const latest={};d.filter(x=>x.program==='TAHFIDZ').forEach(x=>{if(!latest[x.juz]||latest[x.juz].id<x.id)latest[x.juz]=x});const done=Object.values(latest).filter(x=>x.status==='SELESAI').length;c.innerHTML=`<div class="page-card"><h3>Progress Tahfidz — ${done}/30 Juz</h3><div class="progress-grid">${Array.from({length:30},(_,i)=>{const x=latest[i+1];return `<div class="juz ${x?.status==='SELESAI'?'done':x?.status==='DALAM PROSES'?'process':''}"><b>Juz ${i+1}</b><small>${esc(x?.status||'BELUM DIMULAI')}</small></div>`}).join('')}</div></div>`}else{const filtered=page==='progress'?d:d.filter(x=>x.program===page.toUpperCase());c.innerHTML=`<div class="page-card"><h3>${page==='progress'?'Progres Belajar':page.toUpperCase()}</h3>${table(['Tanggal','Program','Juz','Status','Makharij','Tajwid','Kelancaran','Panjang Pendek','Materi','Pemahaman','Nilai','Catatan'],filtered.map(x=>`<tr><td>${esc(x.learning_date)}</td><td>${esc(x.program)}</td><td>${x.juz||'-'}</td><td>${status(x.status)}</td><td>${esc(x.makharij)}</td><td>${esc(x.tajwid)}</td><td>${esc(x.fluency)}</td><td>${esc(x.length_rule)}</td><td>${esc(x.material)}</td><td>${esc(x.understanding)}</td><td>${esc(x.score??'-')}</td><td>${esc(x.notes)}</td></tr>`).join(''))}</div>`}return}
 if(page==='materials'){const d=await api('/api/student/materials');c.innerHTML=`<div class="page-card"><h3>Materi</h3>${table(['Tanggal','Judul','Program','Deskripsi','Guru','File'],d.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.title)}</td><td>${esc(x.program)}</td><td>${esc(x.description)}</td><td>${esc(x.teacher_name||'-')}</td><td>${x.file_path?`<a href="${esc(x.file_path)}" target="_blank">Buka</a>`:'-'}</td></tr>`).join(''))}</div>`;return}
 if(page==='notes'){const d=await api('/api/student/notes');c.innerHTML=`<div class="page-card"><h3>Catatan Guru</h3>${table(['Tanggal','Guru','Catatan'],d.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.teacher_name||'-')}</td><td>${esc(x.content)}</td></tr>`).join(''))}</div>`;return}
 if(page==='payments'){const [d,s]=await Promise.all([api('/api/student/payments'),api('/api/student/payment-info')]);c.innerHTML=`<div class="page-card"><h3>Informasi Pembayaran</h3><p><b>Guru: ${esc(s.teacher_name||'Belum ditetapkan')}</b></p><p><b>NAMA REKENING/E-WALLET</b><br>${esc(s.payment_bank||'-')}</p><p><b>NOMOR REKENING</b><br>${esc(s.payment_account||'-')}</p><p><b>ATAS NAMA</b><br>${esc(s.payment_owner||'-')}</p><form onsubmit="submitPayment(event)" class="form-grid"><div><label>Jumlah</label><input id="spAmount" type="number" required></div><div><label>Metode</label><input id="spMethod" placeholder="Transfer / E-wallet"></div><div><label>Bukti pembayaran</label><input id="spProof" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" required></div><div><label>Catatan</label><input id="spNote"></div><div class="form-actions full"><button class="btn">KIRIM BUKTI PEMBAYARAN</button></div></form></div>${table(['Tanggal','Jumlah','Metode','Status','Bukti','Catatan'],d.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${Number(x.amount).toLocaleString('id-ID')}</td><td>${esc(x.method)}</td><td>${status(x.status)}</td><td>${x.proof_path?`<a href="${x.proof_path}" target="_blank">Buka</a>`:'-'}</td><td>${esc(x.note)}</td></tr>`).join(''))}`;return}
 if(page==='certificates'){const d=await api('/api/student/certificates');c.innerHTML=`<div class="page-card"><h3>Sertifikat</h3><p class="hint">Sertifikat resmi diunggah Admin dalam PDF. Setelah tersedia, Murid dapat membuka, mengunduh, dan mencetak sendiri. Tanda tangan/stempel Baitul Jalal Ilmu Quran diperoleh sesuai prosedur yang berlaku.</p>${table(['Nomor','Program','Pencapaian','Tanggal','Status','PDF','QR'],d.map(x=>`<tr><td>${esc(x.certificate_number)}</td><td>${esc(x.program)}</td><td>${esc(x.achievement)}</td><td>${esc(x.issue_date)}</td><td>${status(x.status)}</td><td>${privateFileButton(x.pdf_path,'DOWNLOAD SERTIFIKAT PDF')}</td><td>${x.qr_path?`<img src="${x.qr_path}" style="width:70px">`:'Verifikasi dengan nomor'}</td></tr>`).join(''))}</div>`;return}
 if(page==='notifications'){const d=await api('/api/notifications');c.innerHTML=`<div class="page-card"><h3>Notifikasi</h3>${table(['Waktu','Judul','Pesan','Jenis','Status'],d.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.title)}</td><td>${esc(x.message)}</td><td>${esc(x.type)}</td><td>${x.is_read?'Dibaca':`<button class="btn small" onclick="readNotification(${x.id})">Tandai dibaca</button>`}</td></tr>`).join(''))}</div>`;return}
}
async function studentAttend(id){try{const d=await api('/api/student/attendance',{method:'POST',body:JSON.stringify({scheduleId:id,method:'AKUN'})});toast(d.message)}catch(e){toast(e.message)}}
async function submitPayment(e){e.preventDefault();try{const proof=await fileToDataUrl($('#spProof'));if(!proof)throw new Error('Bukti pembayaran wajib diunggah.');await api('/api/student/payment',{method:'POST',body:JSON.stringify({amount:$('#spAmount').value,method:$('#spMethod').value,proof,note:$('#spNote').value})});toast('Bukti pembayaran dikirim untuk verifikasi.');dashPage('payments')}catch(x){toast(x.message)}}
async function readNotification(id){try{await api('/api/notifications/read',{method:'POST',body:JSON.stringify({id})});dashPage('notifications')}catch(e){toast(e.message)}}
async function bootPublic(){try{const [programs,teachers,stats,settings]=await Promise.all([api('/api/public/programs'),api('/api/public/teachers'),api('/api/public/stats'),api('/api/public/settings')]);state.settings=settings||state.settings;const pc=$('#programCards');if(pc)pc.innerHTML=programs.map(x=>`<article><h3>${esc(x.name)}</h3><p>${esc(x.description||'')}</p></article>`).join('');const tc=$('#teacherCards');if(tc)tc.innerHTML=teachers.map(x=>`<article>${x.photo?`<img src="${esc(x.photo)}" alt="${esc(x.name)}" style="width:100%;max-height:220px;object-fit:cover;border-radius:14px">`:''}<h3>${esc(x.name)}</h3><p>${esc((x.programs||[]).join(', '))}</p></article>`).join('');const st={teachers:$('#stTeachers'),students:$('#stStudents'),tahfidz:$('#stTahfidz'),tahsin:$('#stTahsin'),tafsir:$('#stTafsir')};Object.entries(st).forEach(([k,e])=>{if(e)e.textContent=Number(stats[k]||0).toLocaleString('id-ID')});const ci=$('#contactInfo');if(ci){const wa=String(state.settings.whatsapp||'').replace(/\D/g,'');const wanum=wa.startsWith('0')?'62'+wa.slice(1):wa;const web=String(state.settings.website||'').trim();const webUrl=web&&/^https?:\/\//i.test(web)?web:(web?'https://'+web:'');const addr=String(state.settings.address||'').trim();ci.innerHTML=`<div><b>WhatsApp</b><br>${wanum?`<a href="https://wa.me/${wanum}" target="_blank" rel="noopener noreferrer">${esc(state.settings.whatsapp)}</a>`:'-'}</div><div><b>Website</b><br>${webUrl?`<a href="${esc(webUrl)}" target="_blank" rel="noopener noreferrer">${esc(web)}</a>`:'-'}</div><div><b>Alamat</b><br>${addr?`<a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(addr)}" target="_blank" rel="noopener noreferrer">${esc(addr)}</a>`:'-'}</div>`;}renderSocialLinks()}catch(e){}}
async function loadPublicSettings(){try{state.settings=await api('/api/public/settings')}catch{state.settings={}}}
function renderSocialLinks(){const c=$('#socialLinks');if(!c)return;const items=[['Facebook',state.settings.social_facebook||''],['Instagram',state.settings.social_instagram||''],['YouTube',state.settings.social_youtube||''],['TikTok',state.settings.social_tiktok||'']];c.innerHTML=items.map(([n,u])=>u?`<a class="social-card" href="${esc(u)}" target="_blank" rel="noopener noreferrer"><strong>${n}</strong><span>BUKA ${n.toUpperCase()}</span></a>`:`<div class="social-card disabled"><strong>${n}</strong><span>LINK BELUM DIATUR</span></div>`).join('')}
async function init(){
 $('#year').textContent=new Date().getFullYear(); await loadPublicSettings(); renderSocialLinks(); await bootPublic();
 if(state.token){try{state.user=(await api('/api/me')).user;showDashboard()}catch{state.token='';localStorage.removeItem('bj_token')}}
}
window.addEventListener('hashchange',()=>{if(!state.user&&location.hash==='#login')openLogin()});
init();
